import{_ as a,o as t,c as i,a2 as s}from"./chunks/framework.doxMM-x8.js";const g=JSON.parse('{"title":"从同一对象详情操作设备","description":"","frontmatter":{"docLocale":"zh","counterpart":"/en/tutorials/device-details","contentType":"tutorial","prev":{"text":"空间工作台","link":"/tutorials/spatial-workbench"},"next":{"text":"设备趋势","link":"/tutorials/device-trends"}},"headers":[],"relativePath":"tutorials/device-details.md","filePath":"tutorials/device-details.md"}'),l={name:"tutorials/device-details.md"};function o(r,e,n,p,d,c){return t(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="从同一对象详情操作设备" tabindex="-1">从同一对象详情操作设备 <a class="header-anchor" href="#从同一对象详情操作设备" aria-label="Permalink to &quot;从同一对象详情操作设备&quot;">​</a></h1><p>目标：从三维空间选择同一个 Entity（对象），区分目标、实际观测、命令和任务结果，并恢复失败的来源重启。</p><h2 id="起始状态与源码" tabindex="-1">起始状态与源码 <a class="header-anchor" href="#起始状态与源码" aria-label="Permalink to &quot;起始状态与源码&quot;">​</a></h2><p>先完成<a href="./spatial-workbench">空间工作台</a>。使用包含本章实现的当前 checkout。准备一个持久 Lab、两台模拟照明和两台模拟离心机。普通 Member 需要有效会话；Agent 使用相同公开接口，但需要有效 <code>lab:full</code> key。</p><p>在仓库根目录运行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --frozen-lockfile</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>打开 <a href="http://127.0.0.1:5173/lab" target="_blank" rel="noreferrer">http://127.0.0.1:5173/lab</a>。登录后先显示三维空间。下面的 Start、Stop 和动作会写入开发数据库。</p><p><a href="https://github.com/CaiZongyuan/labworld/blob/847a4609ed29871c5721b4e03dc3edd3953b8f28/packages/views/src/lab/entity-detail.tsx" target="_blank" rel="noreferrer">共享详情</a>提供操作、记录和详情。<a href="https://github.com/CaiZongyuan/labworld/blob/847a4609ed29871c5721b4e03dc3edd3953b8f28/packages/views/src/lab/workbench-context.tsx" target="_blank" rel="noreferrer">工作台上下文</a>按部署、身份、Lab 和 Entity 保留目标和尝试。<a href="https://github.com/CaiZongyuan/labworld/blob/847a4609ed29871c5721b4e03dc3edd3953b8f28/packages/views/src/lab/observation-state.ts" target="_blank" rel="noreferrer">属性判定</a>读取服务器事实，不用心跳推算实际值。设备使用现有<a href="https://github.com/CaiZongyuan/labworld/blob/847a4609ed29871c5721b4e03dc3edd3953b8f28/packages/sdk/src/generated/sdk.gen.ts" target="_blank" rel="noreferrer">生成 SDK</a>，无需新增 API。</p><h2 id="在操作页区分目标与实际值" tabindex="-1">在操作页区分目标与实际值 <a class="header-anchor" href="#在操作页区分目标与实际值" aria-label="Permalink to &quot;在操作页区分目标与实际值&quot;">​</a></h2><ol><li><p>打开对象目录。</p></li><li><p>选择 <code>Light A</code>。</p><p>名称、登记位置、模拟来源和身份类型显示在详情顶部。<strong>操作</strong>显示关键实际值、单位、质量和时间。尚无报告的属性显示<strong>未知 · 无观测</strong>。</p></li><li><p>选择<strong>启动程序</strong>。</p></li><li><p>等待首条观测。</p></li><li><p>将**目标亮度 (%)**设为 <code>23</code>。</p></li><li><p>选择<strong>设置</strong>。</p><p>Command 先显示提交和等待，再显示执行结果。观测亮度只随服务器属性报告变化。accepted 或 succeeded 都不能代替实际观测。</p></li><li><p>选择 <code>Light B</code>。</p></li><li><p>将目标亮度设为 <code>77</code>。</p></li><li><p>返回 <code>Light A</code>。</p><p>A 的目标仍为 <code>23</code>。B 的输入和命令反馈独立。切换对象不会把目标当作测量。<strong>请求电源目标</strong>保留最后请求，与<strong>观测电源</strong>分别显示。</p></li></ol><p>目标和操作尝试只保留在当前工作台会话。刷新页面后读取持久实际状态。它们不是后端设备配置。</p><h2 id="检查当前值和最后报告值" tabindex="-1">检查当前值和最后报告值 <a class="header-anchor" href="#检查当前值和最后报告值" aria-label="Permalink to &quot;检查当前值和最后报告值&quot;">​</a></h2><p>一个属性只有同时满足以下条件，才显示<strong>当前观测</strong>：</p><ul><li>值符合固定定义的类型。<code>false</code> 和 <code>0</code> 都是有效值；<code>null</code> 和缺失值保持未知。</li><li>属性的新鲜度是 <code>current</code>，来源时间已知，质量是 <code>good</code>。</li><li>属性属于当前 Binding（运行绑定）和当前正在运行的 Run（程序运行）。</li></ul><ol><li><p>停止 <code>Light A</code> 的程序。</p><p>已报告的值继续显示为<strong>最后报告值</strong>。原来源和时间保留。Stop 不等于关闭照明。</p></li><li><p>再次启动程序。</p><p>页面显示新的 Run。新 Run 尚未报告的属性继续显示最后值。亮度的新报告不会刷新旧电源属性；心跳也不会刷新它。</p></li><li><p>打开<strong>详情</strong>。</p><p>查看各属性的 Binding、Run、报告序列、来源时间、接收时间、更新时间、有效期、质量和原始新鲜度。当前执行身份与属性原来的身份分别可查。</p></li><li><p>打开<strong>记录</strong>。</p><p>过滤同一 Entity 的既有历史。记录查询不会改变设备状态。保留期和公开查询见<a href="./run-history">运行历史</a>。</p></li></ol><h2 id="恢复来源和不确定命令" tabindex="-1">恢复来源和不确定命令 <a class="header-anchor" href="#恢复来源和不确定命令" aria-label="Permalink to &quot;恢复来源和不确定命令&quot;">​</a></h2><ol><li><p>在无在途任务的运行设备上选择<strong>重启来源</strong>。</p></li><li><p>确认重启。</p><p>页面先请求 Stop，成功后才请求 Start。Stop 失败时，不请求 Start。Stop 成功而 Start 失败时，来源保持停止；选择<strong>启动程序</strong>恢复。新 Run 不续跑旧 Task，也不重放旧动作。</p></li></ol><p>响应丢失时，读取<strong>提交结果不确定</strong>。保留原参数和原 key，选择<strong>重试同一命令</strong>。已有 Command 时，选择<strong>刷新命令</strong>查询原记录。不要用新 key 自动重复动作。旧 Run 的动作不能在新 Run 中重放。</p><p>连接中断或服务不可用时，页面保留最后快照并禁用新操作。恢复连接后再确认服务器状态。身份失效或撤销时，重新登录；旧身份的尝试不能用于新身份。</p><h2 id="完成并取消离心任务" tabindex="-1">完成并取消离心任务 <a class="header-anchor" href="#完成并取消离心任务" aria-label="Permalink to &quot;完成并取消离心任务&quot;">​</a></h2><ol><li><p>选择 <code>Centrifuge A</code>。</p></li><li><p>启动程序。</p></li><li><p>将目标转速设为 <code>6000 rpm</code>，目标温度设为 <code>22 degC</code>，任务时长设为 <code>6 s</code>。</p></li><li><p>选择<strong>开始离心</strong>。</p><p>后端固定任务参数。准备阶段不计入有效任务时间。达到容差后，后端开始有效计时；任务随后减速。</p></li><li><p>等待<strong>已完成</strong>。</p><p>设备回到 idle。completed 结果仍显示。新 Run 和后续空闲观测不会覆盖结束结果。</p></li><li><p>在 <code>Centrifuge B</code> 开始一个 <code>60 s</code> 任务。</p></li><li><p>选择<strong>停止离心</strong>。</p></li><li><p>等待减速结束。</p><p>B 的结果变为 cancelled。A 的目标和结果保持独立。<strong>停止离心</strong>取消 Task；<strong>停止程序</strong>结束 Run。在途任务期间先取消任务并等待空闲，再停止来源。完整参数范围、后端阶段和中断恢复见<a href="./centrifuge-tasks">离心任务</a>。</p></li></ol><h2 id="验证与下一步" tabindex="-1">验证与下一步 <a class="header-anchor" href="#验证与下一步" aria-label="Permalink to &quot;验证与下一步&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vitest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apps/web/src/lab-device-details.test.tsx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apps/web/src/lab-devices.test.tsx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apps/web/src/lab-centrifuges.test.tsx</span></span></code></pre></div><p>该入口操作真实 Lab Views；MSW 只替代 HTTP。真实 Node/Web 浏览器验收另用隔离服务和持久数据。它检查桌面、已批准窄屏、实际 WebGL 像素、焦点和可点击区域。测试不访问你正在使用的开发数据库。</p><p>继续<a href="./device-trends">设备趋势</a>，查看同一设备的真实历史读数、缺口与来源。</p><hr><p>源码版本：<code>847a4609ed29</code> · <a href="https://github.com/CaiZongyuan/labworld/blob/847a4609ed29871c5721b4e03dc3edd3953b8f28/docs/tutorials/device-details.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>`,27)])])}const b=a(l,[["render",o]]);export{g as __pageData,b as default};
